const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Wuhan geometry (approximate bounding box)
  var wuhan = ee.Geometry.Polygon([
    [[114.0, 30.8], [114.6, 30.8], [114.6, 30.4], [114.0, 30.4], [114.0, 30.8]]
  ]);

  // Define time periods
  var period1 = ['2020-01-01', '2020-01-20'];
  var period2 = ['2020-02-10', '2020-02-25'];

  // Get Sentinel-5P NO2 data
  var no2_col1 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(period1[0], period1[1])
    .filterBounds(wuhan)
    .select('NO2_column_number_density');

  var no2_col2 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(period2[0], period2[1])
    .filterBounds(wuhan)
    .select('NO2_column_number_density');

  // Check collection sizes
  var size1 = no2_col1.size().getInfo();
  var size2 = no2_col2.size().getInfo();

  console.log(`Jan 1-20 Images: ${size1}`);
  console.log(`Feb 10-25 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate mean NO2 for each period
  var mean1_img = no2_col1.mean();
  var mean2_img = no2_col2.mean();

  // Get pixel counts and mean values
  var stats1 = mean1_img.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: wuhan,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  var stats2 = mean2_img.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: wuhan,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  var mean1 = stats1.NO2_column_number_density_mean;
  var count1 = stats1.NO2_column_number_density_count;
  var mean2 = stats2.NO2_column_number_density_mean;
  var count2 = stats2.NO2_column_number_density_count;

  console.log(`Jan Mean: ${mean1?.toFixed(6)} mol/m², Pixels: ${count1}`);
  console.log(`Feb Mean: ${mean2?.toFixed(6)} mol/m², Pixels: ${count2}`);

  // Check for valid pixels
  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Validate results
  if (mean1 === null || mean2 === null || 
      isNaN(mean1) || isNaN(mean2) ||
      mean1 < 0 || mean2 < 0 || mean1 > 0.01 || mean2 > 0.01) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare and determine answer
  var decrease = mean2 < mean1;
  var changePercent = ((mean2 - mean1) / mean1 * 100).toFixed(1);

  console.log(`Change: ${changePercent}%`);

  if (decrease) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
